function closeSocketQuietly(socket:WebSocket|null,reason='replaced'){if(!socket)return;socket.onclose=null;socket.onerror=null;if(socket.readyState===WebSocket.OPEN)socket.close(1000,reason);else if(socket.readyState===WebSocket.CONNECTING)socket.onopen=()=>socket.close(1000,reason)}
function initials(name:string){return name.split(/\s+/).filter(Boolean).slice(0,2).map(x=>x[0]).join('').toUpperCase()||'A'}
function bytes(n:number){if(!n)return '—';const u=['B','KB','MB','GB','TB'];let v=n,i=0;while(v>=1024&&i<u.length-1){v/=1024;i++}return `${v>=10?v.toFixed(0):v.toFixed(1)} ${u[i]}`}
function duration(seconds:number){if(seconds<60)return `${seconds}s`;if(seconds<3600)return `${Math.floor(seconds/60)}m`;if(seconds<86400)return `${Math.floor(seconds/3600)}h ${Math.floor(seconds%3600/60)}m`;return `${Math.floor(seconds/86400)}d ${Math.floor(seconds%86400/3600)}h`}
function level(code:string){return ({developer:100,instructor:90,president:80,vice_president:70,secretary:60,treasurer:60,pio:60,mayor:50,admin:40,member:0} as Record<string,number>)[code]??0}
function label(v:string){return v.replaceAll('_',' ').replace(/\b\w/g,m=>m.toUpperCase())}
function sortableTime(value:string){const parsed=Date.parse(value.replace(' · ',' '));return Number.isFinite(parsed)?parsed:0}
function relativeActivity(iso:string|undefined,fallback:string){const t=iso?Date.parse(iso):NaN;if(!Number.isFinite(t))return fallback||'';const seconds=Math.max(0,Math.floor((Date.now()-t)/1000));if(seconds<45)return'now';if(seconds<3600)return`${Math.floor(seconds/60)}m ago`;if(seconds<86400)return`${Math.floor(seconds/3600)}h ago`;if(seconds<604800)return`${Math.floor(seconds/86400)}d ago`;return fallback||new Date(t).toLocaleDateString()}
function detectLibraryType(value:string,file?:File|null){const mime=file?.type.toLowerCase()||'';if(mime.startsWith('image/'))return 'image';if(mime.startsWith('video/'))return 'video';if(mime.startsWith('audio/'))return 'audio';const clean=(file?.name||value).split(/[?#]/)[0].toLowerCase();const ext=clean.includes('.')?clean.split('.').pop()||'':'';if(['jpg','jpeg','png','gif','webp','svg','bmp','avif'].includes(ext))return 'image';if(['mp4','webm','mov','m4v','avi','mkv'].includes(ext))return 'video';if(['mp3','wav','ogg','m4a','aac','flac'].includes(ext))return 'audio';return 'file'}
function libraryExtension(value:string,file?:File|null){const clean=(file?.name||value).split(/[?#]/)[0];const name=clean.split('/').pop()||'';if(!name.includes('.'))return '';const ext=name.split('.').pop()?.trim().toLowerCase()||'';return ext.length<=12?ext:''}
function assessmentImportContent(value:unknown):AssessmentContent{
  if(value&&typeof value==='object'&&!Array.isArray(value)){
    const raw=value as Record<string,unknown>, type=String(raw.type||'text').toLowerCase() as AssessmentContent['type']
    if(type==='image'||type==='video'||type==='audio')return {type,library_id:Number(raw.library_id||0)||undefined,url:String(raw.url||raw.src||'').trim()||undefined,label:String(raw.label||raw.name||'').trim()||undefined}
    return {type:'text',text:String(raw.text||raw.value||'').trim()}
  }
  const text=String(value??'').trim()
  const wrapped=text.match(/^\$\{(image|video|audio)\.(.+)\}$/i)
  if(wrapped)return {type:wrapped[1].toLowerCase() as AssessmentContent['type'],url:wrapped[2].trim(),label:wrapped[2].trim().split('/').pop()||wrapped[1]}
  return {type:'text',text}
}
function assessmentImportQuestion(row:Record<string,any>,index:number,defaultYear:number,baseOrder:number):Question{
  const answers=row.answers&&typeof row.answers==='object'?row.answers:{}
  const questionSource=row.questionContent??row.question??row.quesiton
  const correctSource=row.correctContent??answers.correct??row.correctAnswer??row.correct_answer
  const dummySource=row.dummyContents??answers.dummy??row.dummyAnswers??row.dummy_answers
  if(questionSource==null||correctSource==null||!Array.isArray(dummySource))throw new Error(`Question ${index+1}: expected question/quesiton, answers.correct, and answers.dummy[].`)
  const questionContent=assessmentImportContent(questionSource),correctContent=assessmentImportContent(correctSource),dummyContents=dummySource.map(assessmentImportContent)
  if(dummyContents.length<3)throw new Error(`Question ${index+1}: add at least 3 dummy answers.`)
  return {id:0,question:contentLabel(questionContent),correctAnswer:contentLabel(correctContent),dummyAnswers:dummyContents.map(contentLabel),active:row.active!==false,sort_order:Number(row.sort_order||baseOrder+index),year_level:Number(row.year_level||defaultYear),kind:String(row.kind||'qa'),questionContent,correctContent,dummyContents,metadata:{...(row.metadata||{}),...(row.technology?{technology:row.technology}:{})}}
}
async function optimizeChatImage(file:File){if(!file.type.startsWith('image/')||file.size<900_000)return file;const bitmap=await createImageBitmap(file).catch(()=>null);if(!bitmap)return file;const scale=Math.min(1,1920/Math.max(bitmap.width,bitmap.height));const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(bitmap.width*scale));canvas.height=Math.max(1,Math.round(bitmap.height*scale));const ctx=canvas.getContext('2d');if(!ctx){bitmap.close();return file}ctx.drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();const blob=await new Promise<Blob|null>(resolve=>canvas.toBlob(resolve,'image/jpeg',.82));if(!blob||blob.size>=file.size)return file;return new File([blob],file.name.replace(/\.[^.]+$/,'.jpg'),{type:'image/jpeg',lastModified:Date.now()})}

