  function connectSupport(){if(!supportActiveRef.current)return;setSupportStatus('connecting');if(supportRetryRef.current){window.clearTimeout(supportRetryRef.current);supportRetryRef.current=null}if(supportHeartbeatRef.current){window.clearInterval(supportHeartbeatRef.current);supportHeartbeatRef.current=null}const previous=supportRef.current;supportRef.current=null;closeSocketQuietly(previous,'support replaced');const ws=new WebSocket(websocketURL('/ws/support?mode=admin'));supportRef.current=ws;ws.onopen=()=>{setSupportStatus('online');supportHeartbeatRef.current=window.setInterval(()=>{if(ws.readyState===WebSocket.OPEN)ws.send(JSON.stringify({type:'ping'}))},25000);const thread=selectedThreadRef.current;if(thread)ws.send(JSON.stringify({type:'select',thread_id:thread}))};ws.onmessage=e=>{try{const p=JSON.parse(e.data);if(p.type==='threads')setThreads(p.threads||[]);if(p.type==='history'&&p.thread_id===selectedThreadRef.current){setMessages(p.messages||[]);ws.send(JSON.stringify({type:'seen',thread_id:p.thread_id}))}if(p.type==='message'&&p.thread_id===selectedThreadRef.current){setMessages(x=>[...x.filter(m=>m.id!==p.message.id),p.message]);if(p.message?.sender_kind==='visitor')ws.send(JSON.stringify({type:'seen',thread_id:p.thread_id}))}if(p.type==='seen'&&p.thread_id===selectedThreadRef.current&&p.viewer_kind==='visitor')setMessages(x=>x.map(m=>m.sender_kind==='admin'?{...m,seen:true}:m));if(p.type==='typing'&&p.thread_id===selectedThreadRef.current)setSupportTyping(p.typing?(p.name||'Someone'):'');if(p.type==='reaction'&&p.thread_id===selectedThreadRef.current)setMessages(x=>x.map(m=>m.id===p.message_id?{...m,reactions:p.count,reaction_summary:p.summary||{}}:m));if(p.type==='clear'&&p.thread_id===selectedThreadRef.current)setMessages([])}catch{}};ws.onclose=()=>{if(supportHeartbeatRef.current){window.clearInterval(supportHeartbeatRef.current);supportHeartbeatRef.current=null}if(supportRef.current===ws)supportRef.current=null;setSupportStatus('offline');if(!supportActiveRef.current)return;supportRetryRef.current=window.setTimeout(()=>{supportRetryRef.current=null;if(document.visibilityState==='visible')connectSupport();else supportRetryRef.current=window.setTimeout(connectSupport,1800)},1800)}}
