  async function uploadFiles(files:FileList|null){if(!files?.length)return;setUploading(true);try{const out:Attachment[]=[];for(const original of Array.from(files).slice(0,8)){const f=original.type.startsWith('image/')?await optimizeChatImage(original):original;const kind=f.type.startsWith('image/')?'image':f.type.startsWith('audio/')?'audio':f.type.startsWith('video/')?'video':'file';const limit=kind==='image'?5:kind==='file'?10:kind==='audio'?20:40;if(f.size>limit*1024*1024)throw new Error(`${original.name} exceeds the ${limit} MB ${kind} limit.`);const fd=new FormData();fd.append('file',f);const p=await api('/api/support/upload',{method:'POST',body:fd});out.push(p.attachment)}setSupportUploads(x=>[...x,...out].slice(0,8))}catch(e){setToast(e instanceof Error?e.message:'Attachment upload failed.')}finally{setUploading(false);if(fileRef.current)fileRef.current.value=''}}
  async function toggleRecording(){
    if(recording){mediaRecorderRef.current?.stop();return}
    if(!navigator.mediaDevices?.getUserMedia||typeof MediaRecorder==='undefined'){setToast('Audio recording is not supported by this browser.');return}
    try{const stream=await navigator.mediaDevices.getUserMedia({audio:true});mediaStreamRef.current=stream;const chunks:BlobPart[]=[];const recorder=new MediaRecorder(stream);mediaRecorderRef.current=recorder;recorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data)};recorder.onstop=()=>{setRecording(false);stream.getTracks().forEach(t=>t.stop());mediaStreamRef.current=null;mediaRecorderRef.current=null;const blob=new Blob(chunks,{type:recorder.mimeType||'audio/webm'});if(!blob.size)return;const ext=blob.type.includes('ogg')?'ogg':blob.type.includes('mp4')?'m4a':'webm';const f=new File([blob],`voice-${Date.now()}.${ext}`,{type:blob.type||'audio/webm'});void (async()=>{setUploading(true);try{const fd=new FormData();fd.append('file',f);const p=await api('/api/support/upload',{method:'POST',body:fd});const attachment=p.attachment as Attachment;setSupportUploads(current=>[...current,attachment].slice(0,8));setToast('Voice recording attached. Review it, then press Send.')}catch(e){setToast(e instanceof Error?e.message:'Voice message could not be uploaded.')}finally{setUploading(false)}})()};recorder.start();setRecording(true)}catch{setToast('Microphone permission was not granted.')}
  }
