  async function saveLibrary(item:LibraryItem,file?:File|null,force=false){
    const duplicate=!item.id?library.find(x=>(!file&&item.url&&x.url.trim().toLowerCase()===item.url.trim().toLowerCase())||(x.label.trim().toLowerCase()===item.label.trim().toLowerCase()&&x.type===item.type)):undefined
    if(duplicate&&!force){
      askConfirm('Possible duplicate',`“${duplicate.label}” already exists in Library. Continue checking this item?`,()=>{void saveLibrary(item,file,true)},'Continue','primary')
      return
    }
    setUploading(true)
    try{
      let target={...item}
      if(file){
        const fd=new FormData()
        fd.append('file',file)
        fd.append('label',item.label||file.name)
        fd.append('location','Library')
        fd.append('reason',item.reason||'')
        if(force)fd.append('reuse_duplicate','1')
        const response=await fetch('/api/admin/library/upload',{method:'POST',body:fd,credentials:'include',cache:'no-store'})
        const uploaded=await response.json().catch(()=>({}))
        if(response.status===409&&uploaded.duplicate&&uploaded.existing&&!force){
          const existing=uploaded.existing as {label?:string;url?:string}
          askConfirm('Identical file already exists',`This upload is byte-for-byte identical to “${existing.label||'an existing Library item'}”. Reuse the existing asset instead of storing another copy?`,()=>{void saveLibrary(item,file,true)},'Reuse existing','primary')
          return
        }
        if(!response.ok)throw new Error(uploaded.error||'Library upload failed.')
        if(uploaded.reused){
          setLibraryModal(undefined)
          setLibrarySeedFile(null)
          await loadLibrary()
          setToast(`Existing Library asset reused: ${uploaded.item?.label||item.label||file.name}.`)
          return
        }
        target={...target,id:Number(uploaded.id||0),url:String(uploaded.item?.url||''),type:item.type||String(uploaded.item?.type||detectLibraryType('',file)),source:'upload'}
      }
      await api('/api/admin/library',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:target.id,label:target.label,type:target.type,url:target.url,location:target.location||'Library',reason:target.reason,active:target.active,visibility:target.visibility||'organization',division_id:target.division_id||0})})
      setLibraryModal(undefined)
      setLibrarySeedFile(null)
      await loadLibrary()
      setToast(item.id?'Library record updated.':'Library item added.')
    }catch(e){
      setToast(e instanceof Error?e.message:'Library item could not be saved.')
    }finally{
      setUploading(false)
    }
  }
