  async function importAssessmentJSON(raw:string){if(!divisionQuestions)return;try{const parsed=JSON.parse(raw);const rows=Array.isArray(parsed)?parsed:(parsed&&typeof parsed==='object'&&Array.isArray((parsed as {questions?:unknown[]}).questions)?(parsed as {questions:unknown[]}).questions:[]);if(!rows.length)throw new Error('JSON must be a non-empty array or an object with a non-empty questions array.');let added=0;for(let i=0;i<rows.length;i++){if(!rows[i]||typeof rows[i]!=='object'||Array.isArray(rows[i]))throw new Error(`Question ${i+1}: each item must be an object.`);const question=assessmentImportQuestion(rows[i] as Record<string,any>,i,assessmentImportYear,divisionQuestions.items.length+1);await api(`/api/admin/divisions/${divisionQuestions.division.id}/assessments`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(question)});added++}setAssessmentImportOpen(false);await openAssessments(divisionQuestions.division);setToast(`${added} assessment question(s) imported.`)}catch(e){setToast(e instanceof Error?e.message:'Assessment JSON could not be imported.')}}

